        const auto before=residentQuestSnapshot();press(sf::Keyboard::J);key(sf::Keyboard::Tab);key(sf::Keyboard::Tab);assert(fieldJournalPanel().questTab() && !isChatMode);key(sf::Keyboard::Tab,true);press(sf::Keyboard::Down);press(sf::Keyboard::Down);press(sf::Keyboard::Down);assert(fieldJournalPanel().selectedQuest()==2);click(ResidentQuestLogView::row(0),true);assert(fieldJournalPanel().selectedQuest()==2);click(ResidentQuestLogView::row(mode));
